class Completed {

    public void merge(int[] nums1, int m, int[] nums2, int n) {

        int i = m - 1;
        int j = n - 1;
        int k = m + n - 1;

        while (i >= 0 && j >= 0) {

            if (nums1[i] > nums2[j]) {
                nums1[k] = nums1[i];
                i--;
            } else {
                nums1[k] = nums2[j];
                j--;
            }

            k--;
        }

        while (j >= 0) {
            nums1[k] = nums2[j];
            j--;
            k--;
        }
    }
}

class Solution {
//    nums1 = [1,2,3,0,0,0], m = 3
//    nums2 = [2,5,6], n = 3
//            [1,2,2,3,5,6]
    public void merge(int[] nums1, int m, int[] nums2, int n) {
        for (int i=0; i<m; i++){
//            System.out.println(i);
            for (int j=i; j<n; j++){
//                System.out.print(j+", ");
                if (j<i){
                    shiftRight(nums1,i);
                    m++;
                    nums1[i]=nums2[j];
                    break;
                }
            }
            System.out.println();
        }
    }
    private void shiftRight(int[] nums1,int pivot) {
        for (int i = nums1.length-1; i > pivot; i--) {
            nums1[i]=nums1[i=1];
        }
    }
}

